-- Casos raros para probar la copia de esquemas (ver test_esquema.py). Sintético, no es el esquema real.
create schema if not exists extensions;
create table public."order" (
  "desc"   integer generated by default as identity primary key,
  "user"   text not null default 'x''y',
  "Mayúsc" text
);
comment on table public."order" is 'Tabla con nombre reservado y una ''comilla''';
comment on column public."order"."user" is 'Columna reservada';

create sequence public.mi_secuencia_rara;
create table public.serial_renombrado (
  id   bigint not null default nextval('public.mi_secuencia_rara'),
  area numeric generated always as (id * 2) stored,
  dato text
);
alter sequence public.mi_secuencia_rara owned by public.serial_renombrado.id;
alter table public.serial_renombrado add primary key (id);

create table public.identidad_con_inicio (
  id bigint generated always as identity (start with 1000 increment by 10) primary key
);

create table public.particionada (id integer, v text) partition by range (id);
create materialized view public.vista_mat as select 1 as uno;

create function public.peligrosa() returns integer language sql security definer as $$ select 1 $$;
create view public.con_opciones with (security_invoker = true, security_barrier = true) as select id from public.serial_renombrado;
create unique index serial_dato_unico on public.serial_renombrado (dato) where dato is not null;
create publication pub_prueba for table public.identidad_con_inicio;
